package solution

import "testing"

func TestWordCount(t *testing.T) {
	got := WordCount("the cat sat the cat")
	if got["the"] != 2 { t.Errorf("the: want 2 got %d", got["the"]) }
	if got["cat"] != 2 { t.Errorf("cat: want 2 got %d", got["cat"]) }
	if got["sat"] != 1 { t.Errorf("sat: want 1 got %d", got["sat"]) }
}

func TestWordCountEmpty(t *testing.T) {
	if len(WordCount("")) != 0 {
		t.Error("empty string should return empty map")
	}
}

func TestWordCountSingle(t *testing.T) {
	got := WordCount("hello")
	if got["hello"] != 1 { t.Errorf("hello: want 1 got %d", got["hello"]) }
}

